// HAND-OWNED (quick-log). Not generated by Bubblewrap. "Native reminders" switch (P6, DL-03 / TWA-R1).
package io.github.palo007.twa.quicklog

import android.content.Context
import android.content.Intent
import android.content.SharedPreferences

/** DL-03: ask once, only when the Questa (Kotlin) app is found and native reminders are still ON. */
internal fun shouldAskOwner(ownerFound: Boolean, alreadyAsked: Boolean, enabled: Boolean): Boolean =
    ownerFound && !alreadyAsked && enabled

/** DL-03: "Yes, let the Questa app fire reminders" -> native OFF; "No" -> stays ON. */
internal fun enabledAfterAnswer(yes: Boolean): Boolean = !yes

/**
 * Own small prefs file (not questa_quicklog.xml, which holds the Dropbox token and is excluded from
 * backup), so the user's choice survives a backup restore.
 */
object ReminderPrefs {
    /** Agreed with the Kotlin app (CR-TWA-005 §3): an exported no-op component with this action. */
    const val ACTION_REMINDER_OWNER = "io.github.palo007.questa.action.REMINDER_OWNER"
    private const val FILE = "questa_reminders"
    private const val KEY_ENABLED = "native_enabled"
    private const val KEY_OWNER_ASKED = "owner_asked"

    private fun prefs(ctx: Context): SharedPreferences =
        ctx.applicationContext.getSharedPreferences(FILE, Context.MODE_PRIVATE)

    @JvmStatic
    fun isEnabled(ctx: Context): Boolean = prefs(ctx).getBoolean(KEY_ENABLED, true)

    fun setEnabled(ctx: Context, on: Boolean) {
        prefs(ctx).edit().putBoolean(KEY_ENABLED, on).apply()
    }

    fun ownerAsked(ctx: Context): Boolean = prefs(ctx).getBoolean(KEY_OWNER_ASKED, false)

    fun markOwnerAsked(ctx: Context) {
        prefs(ctx).edit().putBoolean(KEY_OWNER_ASKED, true).apply()
    }

    /** True when another installed package exposes the owner action (receiver, activity or service). */
    fun otherOwnerInstalled(ctx: Context): Boolean = try {
        val pm = ctx.packageManager
        val intent = Intent(ACTION_REMINDER_OWNER)
        val pkgs = HashSet<String>()
        pm.queryBroadcastReceivers(intent, 0).forEach { r -> r.activityInfo?.let { if (it.exported) pkgs.add(it.packageName) } }
        pm.queryIntentActivities(intent, 0).forEach { r -> r.activityInfo?.let { if (it.exported) pkgs.add(it.packageName) } }
        pm.queryIntentServices(intent, 0).forEach { r -> r.serviceInfo?.let { if (it.exported) pkgs.add(it.packageName) } }
        pkgs.remove(ctx.packageName)
        pkgs.isNotEmpty()
    } catch (t: RuntimeException) {
        false
    }
}
